export type UILanguage = "en" | "bn" | "az" | "hi" | "ky" | "tg" | "uz" | "ur" | "ar" | "tr";

export interface LanguageOption {
  code: UILanguage;
  country: string;
  nativeName: string;
  englishName: string;
  flag: string;
}

// Right-to-left scripts (Urdu Nastaliq + Arabic). Used to flip layout direction.
export const RTL_LANGS = new Set<UILanguage>(["ur", "ar"]);
export function isRTL(lang: UILanguage): boolean { return RTL_LANGS.has(lang); }

// Order: English (default) first, then Bangladesh, then others alphabetically by country.
