// English is the source of truth and the universal fallback. The other
// languages are optional — anything missing falls back to English at lookup
// time via t(). This keeps types strict without requiring all 150+ strings
// to be hand-translated for every newly added language up-front.
type Dict = Partial<Record<UILanguage, string>> & { en: string };

